const mongoose = require('mongoose');

/**
 * AdVisit Schema
 * Stores website visitor tracking, device fingerprint, bot signals,
 * user behaviour, and fraud scoring evidence for all traffic sources.
 */
const AdVisitSchema = new mongoose.Schema(
    {
        // Unique visit identifier generated by client (crypto.randomUUID)
        visitId: {
            type: String,
            required: [true, 'visitId is required'],
            unique: true,
            trim: true,
            index: true
        },

        // Multi-brand identifier (e.g. 'pennyscroll', 'specreveal', 'blogzenix', 'trendfiltered')
        brandId: {
            type: String,
            default: 'pennyscroll',
            trim: true,
            index: true
        },

        // Advertising / Campaign Identifiers
        gclid: {
            type: String,
            default: null,
            trim: true,
            index: true
        },
        gadSource: {
            type: String,
            default: null,
            trim: true
        },

        // Traffic Classification
        trafficSource: {
            type: String,
            required: true,
            default: 'Unknown',
            index: true
        },
        trafficMedium: {
            type: String,
            default: null,
            trim: true
        },
        trafficCampaign: {
            type: String,
            default: null,
            trim: true
        },
        referrer: {
            type: String,
            default: '',
            trim: true
        },

        // Server-Side Network & Geolocation Metadata (Collected strictly server-side)
        ip: {
            type: String,
            required: [true, 'ip is required'],
            trim: true,
            index: true
        },
        country: {
            type: String,
            default: 'UNKNOWN',
            trim: true
        },
        cfTimezone: {
            type: String,
            default: null,
            trim: true
        },
        asn: {
            type: String,
            default: null,
            trim: true
        },
        ua: {
            type: String,
            default: '',
            trim: true
        },
        path: {
            type: String,
            default: '/',
            trim: true
        },
        landingPage: {
            type: String,
            default: '/',
            trim: true
        },

        // Query & ValueTrack Parameters
        params: {
            kw: { type: String, default: null },
            network: { type: String, default: null },
            device: { type: String, default: null },
            mt: { type: String, default: null },
            utm_source: { type: String, default: null },
            utm_medium: { type: String, default: null },
            utm_campaign: { type: String, default: null },
            utm_content: { type: String, default: null },
            utm_term: { type: String, default: null }
        },

        // Browser Fingerprint (SHA-256 hash excluding User-Agent)
        fpHash: {
            type: String,
            required: [true, 'fpHash is required'],
            trim: true,
            index: true
        },

        // Raw Bot Detection Signals
        signals: {
            webdriver: { type: Boolean, default: false },
            headless: { type: Boolean, default: false },
            softwareWebGL: { type: Boolean, default: false },
            hasLanguages: { type: Boolean, default: true },
            languages: [{ type: String }],
            platform: { type: String, default: '' },
            cores: { type: Number, default: 0 },
            memory: { type: Number, default: 0 },
            screen: {
                width: { type: Number, default: 0 },
                height: { type: Number, default: 0 },
                colorDepth: { type: Number, default: 0 },
                pixelRatio: { type: Number, default: 1 }
            },
            touchSupport: { type: Boolean, default: false },
            timezone: { type: String, default: '' },
            webglVendor: { type: String, default: '' },
            webglRenderer: { type: String, default: '' }
        },

        // Visitor Behaviour Activity (Counts only - NO keystrokes or text)
        behaviour: {
            pointerMoves: { type: Number, default: 0 },
            touchMoves: { type: Number, default: 0 },
            scrollEvents: { type: Number, default: 0 },
            maxScrollDepth: { type: Number, default: 0 },
            clicks: { type: Number, default: 0 },
            keyPresses: { type: Number, default: 0 },
            visibleTimeMs: { type: Number, default: 0 }
        },
        behaviourSeen: {
            type: Boolean,
            default: false
        },

        // Fraud Scoring Engine Results
        score: {
            type: Number,
            default: 0,
            index: true
        },
        why: [{
            type: String
        }],
        risk: {
            type: String,
            enum: ['Low', 'Medium', 'High'],
            default: 'Low',
            index: true
        }
    },
    {
        timestamps: true
    }
);

// Indexes
AdVisitSchema.index({ createdAt: 1 }, { expireAfterSeconds: 60 * 24 * 3600 }); // 60 days TTL
AdVisitSchema.index({ fpHash: 1, createdAt: -1 }); // Rotating proxy analysis
AdVisitSchema.index({ fpHash: 1, ip: 1 }); // Fingerprint / IP mapping
AdVisitSchema.index({ brandId: 1, fpHash: 1, createdAt: -1 }); // Multi-brand cluster lookup
AdVisitSchema.index({ brandId: 1, score: -1, createdAt: -1 }); // Brand evidence reporting

/**
 * Helper to obtain or compile the AdVisit model on any Mongoose connection
 */
function getAdVisitModel(connection = mongoose) {
    if (connection.models && connection.models.AdVisit) {
        return connection.models.AdVisit;
    }
    return connection.model('AdVisit', AdVisitSchema);
}

module.exports = {
    AdVisitSchema,
    getAdVisitModel,
    AdVisit: mongoose.models.AdVisit || mongoose.model('AdVisit', AdVisitSchema)
};

